static int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int x : nums) freq.merge(x, 1, Integer::sum);
    // 小顶堆，堆顶是当前 K 个里频次最低的；频次相同再比数值，比较器必须是全序
    // 换成「数值前 K 大」：去掉 Map，比较器改为 (a, b) -> Integer.compare(a, b)，堆里直接放元素
    PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> {
        int c = Integer.compare(freq.get(a), freq.get(b));
        return c != 0 ? c : Integer.compare(a, b);
    }
    );
    for (int x : freq.keySet()) {
        pq.offer(x);
        if (pq.size() > k) pq.poll();
    }
    int[] ans = new int[k];
    // poll 是频次从低到高；倒着填后高频在前。样例 k=2 得到 [1, 2]
    for (int i = k - 1;
    i >= 0;
    i--) ans[i] = pq.poll();
    return ans;
}

static class MedianFinder {
    // lo 存较小的一半（大顶堆，堆顶是左半最大）；hi 存较大的一半（小顶堆）
    // 始终保持 lo 中每个数 <= hi 中每个数，且 lo.size() == hi.size() 或恰好多 1
    private final PriorityQueue<Integer> lo = new PriorityQueue<>((a, b) -> Integer.compare(b, a));
    private final PriorityQueue<Integer> hi = new PriorityQueue<>();
    public void addNum(int num) {
        lo.offer(num);
        hi.offer(lo.poll());
        if (hi.size() > lo.size()) lo.offer(hi.poll());
    }
    public double findMedian() {
        // 调用前至少 add 过一个数。奇数个答案是 lo 堆顶；偶数个是两顶的平均
        if (lo.size() > hi.size()) return lo.peek();
        return ((long) lo.peek() + hi.peek()) / 2.0;
    }
}

