class Solution {
    public void bubbleSort(int[] nums) {
        // end 是尚未就位的右端，本轮最大值会沉到这里
        for (int end = nums.length - 1;
        end > 0;
        end--) {
            boolean swapped = false;
            for (int i = 0;
            i < end;
            i++) {
                if (nums[i] > nums[i + 1]) {
                    swap(nums, i, i + 1);
                    swapped = true;
                }
            }
            if (!swapped) return;
            // 本轮无交换，数组已经有序
        }
    }
    public void selectionSort(int[] nums) {
        for (int i = 0;
        i < nums.length - 1;
        i++) {
            int minIndex = i;
            // 在尚未排序的 [i, n) 中找最小元的下标
            for (int j = i + 1;
            j < nums.length;
            j++) {
                if (nums[j] < nums[minIndex]) minIndex = j;
            }
            swap(nums, i, minIndex);
        }
    }
    public void insertionSort(int[] nums) {
        for (int i = 1;
        i < nums.length;
        i++) {
            int key = nums[i];
            int j = i - 1;
            // 大于 key 的元素右移，给 key 腾出插入位置
            while (j >= 0 && nums[j] > key) {
                nums[j + 1] = nums[j];
                j--;
            }
            nums[j + 1] = key;
        }
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.*;
class Solution {
    private final Random random = new Random();
    public int[] sortArray(int[] nums) {
        quickSort(nums, 0, nums.length - 1);
        return nums;
    }
    private void quickSort(int[] nums, int left, int right) {
        if (left >= right) return;
        // 随机取枢轴值，降低固定一端在有序输入上退化的概率
        int pivot = nums[left + random.nextInt(right - left + 1)];
        int less = left;
        int current = left;
        int greater = right;
        while (current <= greater) {
            if (nums[current] < pivot) {
                // 划入小于段，current 换来的值已经看过
                swap(nums, less++, current++);
            } else if (nums[current] > pivot) {
                // 划入大于段，换到 current 的新值还要再比较
                swap(nums, current, greater--);
            } else {
                current++;
            }
        }
        // [less, greater] 等于枢轴，已在最终位置
        quickSort(nums, left, less - 1);
        quickSort(nums, greater + 1, right);
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

class Solution {
    public int[] sortArray(int[] nums) {
        int[] temp = new int[nums.length];
        mergeSort(nums, temp, 0, nums.length - 1);
        return nums;
    }
    private void mergeSort(int[] nums, int[] temp, int left, int right) {
        if (left >= right) return;
        // 避免 (left+right) 溢出，并切成左右两段
        int mid = left + (right - left) / 2;
        mergeSort(nums, temp, left, mid);
        mergeSort(nums, temp, mid + 1, right);
        merge(nums, temp, left, mid, right);
    }
    private void merge(int[] nums, int[] temp, int left, int mid, int right) {
        int i = left;
        int j = mid + 1;
        int write = left;
        while (i <= mid && j <= right) {
            // 相等先取左边，相等元素的相对顺序不变
            if (nums[i] <= nums[j]) temp[write++] = nums[i++];
            else temp[write++] = nums[j++];
        }
        while (i <= mid) temp[write++] = nums[i++];
        while (j <= right) temp[write++] = nums[j++];
        // temp 中 [left, right] 已合并有序，抄回原数组
        for (int k = left;
        k <= right;
        k++) {
            nums[k] = temp[k];
        }
    }
}

class Solution {
    public int[] sortArray(int[] nums) {
        int n = nums.length;
        // 最后一个非叶结点开始，自底向上建成最大堆
        for (int root = n / 2 - 1;
        root >= 0;
        root--) {
            siftDown(nums, root, n);
        }
        // 堆顶是当前最大值，换到 end 后不再属于堆
        for (int end = n - 1;
        end > 0;
        end--) {
            swap(nums, 0, end);
            siftDown(nums, 0, end);
        }
        return nums;
    }
    private void siftDown(int[] nums, int root, int heapSize) {
        while (true) {
            int left = root * 2 + 1;
            if (left >= heapSize) return;
            int right = left + 1;
            int largest = left;
            // 右孩子存在且更大时，沿右孩子下沉
            if (right < heapSize && nums[right] > nums[left]) {
                largest = right;
            }
            if (nums[root] >= nums[largest]) return;
            swap(nums, root, largest);
            root = largest;
        }
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.Random;
public class QuickSortDemo {
    private final Random random = new Random();
    public void quickSort(int[] nums) {
        sort(nums, 0, nums.length - 1);
    }
    private void sort(int[] nums, int left, int right) {
        if (left >= right) {
            return;
        }
        // 随机主元，避免序列接近有序时总选到端点
        int pivotIndex = left + random.nextInt(right - left + 1);
        int newIndex = partition(nums, left, right, pivotIndex);
        // 主元已在最终位置，左右两段分开排
        sort(nums, left, newIndex - 1);
        sort(nums, newIndex + 1, right);
    }
    private int partition(int[] nums, int left, int right, int pivotIndex) {
        int pivot = nums[pivotIndex];
        swap(nums, pivotIndex, right);
        int store = left;
        for (int i = left;
        i < right;
        i++) {
            // 小于主元的元素换到左侧
            if (nums[i] < pivot) {
                swap(nums, store, i);
                store++;
            }
        }
        // 主元放到 store，该下标就是左右分界
        swap(nums, store, right);
        return store;
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.*;
class Solution {
    private final Random random = new Random();
    public int findKthLargest(int[] nums, int k) {
        // 第 k 大 = 升序数组中下标 n-k 的元素。
        int target = nums.length - k;
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            // 随机选枢轴，降低已经有序等输入导致退化的概率。
            int pivot = nums[left + random.nextInt(right - left + 1)];
            int[] equalRange = partition3(nums, left, right, pivot);
            if (target < equalRange[0]) {
                right = equalRange[0] - 1;
            } else if (target > equalRange[1]) {
                left = equalRange[1] + 1;
            } else {
                // target 落在等于 pivot 的区间内，答案已经确定。
                return nums[target];
            }
        }
        throw new IllegalArgumentException("k 超出范围");
    }
    // 三路划分：
    // [left, less) < pivot
    // [less, greater] == pivot
    // (greater, right] > pivot
    private int[] partition3(int[] nums, int left, int right, int pivot) {
        int less = left;
        int current = left;
        int greater = right;
        while (current <= greater) {
            if (nums[current] < pivot) {
                swap(nums, less++, current++);
            } else if (nums[current] > pivot) {
                swap(nums, current, greater--);
            } else {
                current++;
            }
        }
        return new int[]{
            less, greater
        }
        ;
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.Random;
public class MedianInUnsortedArray {
    private final Random random = new Random();
    public int median(int[] nums) {
        // 偶数长度取上中位数，目标就是下标 length/2
        int targetIndex = nums.length / 2;
        return quickSelect(nums, 0, nums.length - 1, targetIndex);
    }
    private int quickSelect(int[] nums, int left, int right, int targetIndex) {
        while (left <= right) {
            // 随机主元，避免总挑到固定位置
            int pivotIndex = left + random.nextInt(right - left + 1);
            int newIndex = partition(nums, left, right, pivotIndex);
            if (newIndex == targetIndex) {
                return nums[newIndex];
            } else if (newIndex < targetIndex) {
                // 目标在右半，丢掉左侧
                left = newIndex + 1;
            } else {
                right = newIndex - 1;
            }
        }
        return -1;
    }
    private int partition(int[] nums, int left, int right, int pivotIndex) {
        int pivot = nums[pivotIndex];
        // 主元先放到末尾，扫描时不会被换走
        swap(nums, pivotIndex, right);
        int store = left;
        for (int i = left;
        i < right;
        i++) {
            // 更小的元素堆到 store 左侧
            if (nums[i] < pivot) {
                swap(nums, store, i);
                store++;
            }
        }
        // store 左侧都更小，主元归位后的下标就是排名
        swap(nums, store, right);
        return store;
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int num : nums) {
            frequency.put(num, frequency.getOrDefault(num, 0) + 1);
        }
        // 频率最大不会超过 nums.length，用“频率”作为桶下标。
        List<List<Integer>> buckets = new ArrayList<>(nums.length + 1);
        for (int i = 0;
        i <= nums.length;
        i++) {
            buckets.add(new ArrayList<>());
        }
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            buckets.get(entry.getValue()).add(entry.getKey());
        }
        int[] answer = new int[k];
        int write = 0;
        // 从最高频率向下收集，直到拿满 k 个。
        for (int count = nums.length;
        count >= 1 && write < k;
        count--) {
            for (int value : buckets.get(count)) {
                answer[write++] = value;
                if (write == k) break;
            }
        }
        return answer;
    }
}

import java.util.*;
// Java 常用集合、队列、堆与数组工具
class MedianFinder {
    // smaller：大根堆，保存较小的一半；larger：小根堆，保存较大的一半。
    private final PriorityQueue<Integer> smaller =
    new PriorityQueue<>(Collections.reverseOrder());
    private final PriorityQueue<Integer> larger = new PriorityQueue<>();
    public MedianFinder() {
    }
    public void addNum(int num) {
        // 先放入较小一半，再把其中最大值移动到较大一半，保证左右有序关系。
        smaller.offer(num);
        larger.offer(smaller.poll());
        // 让 smaller 的数量始终等于 larger，或只多 1 个。
        if (larger.size() > smaller.size()) {
            smaller.offer(larger.poll());
        }
    }
    public double findMedian() {
        if (smaller.size() > larger.size()) {
            return smaller.peek();
            // 奇数个时中位数在较小一半的堆顶。
        }
        // 先转 long 再相加，避免两个 int 边界值相加溢出。
        return ((long) smaller.peek() + larger.peek()) / 2.0;
    }
}

import java.util.*;
class Solution {
    static class Entry {
        int value;
        int arrayIndex;
        int elementIndex;
        Entry(int value, int arrayIndex, int elementIndex) {
            this.value = value;
            this.arrayIndex = arrayIndex;
            this.elementIndex = elementIndex;
        }
    }
    public int[] mergeSortedArrays(int[][] arrays) {
        int total = 0;
        // 堆中每个元素是某条数组当前尚未合并的头。
        PriorityQueue<Entry> heap = new PriorityQueue<>(Comparator.comparingInt(e -> e.value));
        for (int i = 0;
        i < arrays.length;
        i++) {
            total += arrays[i].length;
            if (arrays[i].length > 0) {
                heap.offer(new Entry(arrays[i][0], i, 0));
            }
        }
        int[] answer = new int[total];
        int write = 0;
        while (!heap.isEmpty()) {
            Entry cur = heap.poll();
            answer[write++] = cur.value;
            int nextIndex = cur.elementIndex + 1;
            // 只把刚弹出的那一条数组的下一个元素补回堆。
            if (nextIndex < arrays[cur.arrayIndex].length) {
                heap.offer(new Entry(
                arrays[cur.arrayIndex][nextIndex],
                cur.arrayIndex,
                nextIndex));
            }
        }
        return answer;
    }
}
